using System;using System.IO;using System.Text;using System.Collections;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckTargetLaunch {
// Development-only physical approach trials. Only software keyboard input drives the truck.
public sealed class TargetRangeProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsTargetRange")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.TargetRange",false);UnityEditor.SessionState.SetBool("LWS.TargetRange",false);
#endif
 if(run){var root=new GameObject("Target real keyboard speed range trials");DontDestroyOnLoad(root);if(FindAnyObjectByType<SportsProbeInputIsolation>()==null)root.AddComponent<SportsProbeInputIsolation>();root.AddComponent<TargetRangeProbe>();}}
 Keyboard keyboard;InputSettings original,settings;TargetMatch match;string folder;int errors;readonly StringBuilder report=new StringBuilder();
 void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;Write();}void Write(){File.WriteAllText(folder+"/progress.txt",report.ToString());}void Error(string s,string stack,LogType kind){if(kind==LogType.Error||kind==LogType.Exception){errors++;report.AppendLine("ERROR "+s+"\n"+stack);Write();}}
 IEnumerator Capture(string name){var camera=match.cameras[0];var rt=new RenderTexture(1280,720,24);rt.Create();var old=camera.targetTexture;camera.targetTexture=rt;yield return null;match.director.Present(.02f);camera.Render();var active=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(1280,720,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1280,720),0,0);texture.Apply();File.WriteAllBytes(folder+"/"+name+"-camera-only.png",texture.EncodeToPNG());Destroy(texture);camera.targetTexture=old;RenderTexture.active=active;rt.Release();Destroy(rt);}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("TargetRangeEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;original=InputSystem.settings;settings=Instantiate(original);settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;
#if UNITY_EDITOR
 settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
#endif
 InputSystem.settings=settings;keyboard=InputSystem.AddDevice<Keyboard>();yield return SportsProbeScene.Ensure<TargetMatch>("TruckTargetLaunch");match=FindAnyObjectByType<TargetMatch>();yield return null;match.setup.count=1;match.NormalizeSetup();match.setup.players[0].source=BowlingSource.Keyboard;var racer=match.racers[0];float[] speeds={16,19,22,25,23.5f,24.5f};
 foreach(float speed in speeds){InputSystem.QueueStateEvent(keyboard,new KeyboardState());match.SetupScreen();match.seed=42761;Check(match.StartMatch(),"solo real approach starts desiredSpeed="+speed);Time.timeScale=4;bool launched=false,paused=false,captured=false;float flightStart=0,deadline=Time.realtimeSinceStartup+70,next=0;while(!match.rules.resolved[0]&&Time.realtimeSinceStartup<deadline){if(match.Stage==TargetStage.Playing&&racer.Phase==TargetFlight.Approach){float desired=speed>=25?1:speed-racer.truck.body.linearVelocity.z;InputSystem.QueueStateEvent(keyboard,desired>.25f?new KeyboardState(match.setup.players[0].forward):desired<-.3f?new KeyboardState(match.setup.players[0].back):new KeyboardState());}else InputSystem.QueueStateEvent(keyboard,new KeyboardState());if(racer.Phase==TargetFlight.Airborne){if(!launched){launched=true;flightStart=match.Clock;report.AppendLine("RELEASE desired="+speed+" velocity="+racer.LaunchVelocity.ToString("F3")+" position="+racer.truck.body.position.ToString("F3"));Write();}if(!paused&&speed==22&&racer.FlightAge>.5f){match.Pause();var p=racer.truck.body.position;var v=racer.truck.body.linearVelocity;float clock=match.Clock;yield return new WaitForSecondsRealtime(.15f);Check(match.Paused&&p==racer.truck.body.position&&v==racer.truck.body.linearVelocity&&clock==match.Clock,"actual mid-flight pause preserves pose velocity and clock");match.Resume();Time.timeScale=4;paused=true;}if(!captured&&racer.FlightAge>.8f&&speed==22){yield return Capture("straight-22-flight");captured=true;}}if(Time.realtimeSinceStartup>next){File.WriteAllText(folder+"/live.txt","desired="+speed+" phase="+racer.Phase+" position="+racer.truck.body.position+" velocity="+racer.truck.body.linearVelocity+" command="+match.commands[0]);next=Time.realtimeSinceStartup+2;}yield return null;}
 InputSystem.QueueStateEvent(keyboard,new KeyboardState());Check(launched&&match.rules.resolved[0],"real no-steer/no-aftertouch delivery resolves desired="+speed);report.AppendLine("TRIAL desired="+speed+" launch="+racer.LaunchVelocity.ToString("F3")+" landing="+racer.LandingPoint.ToString("F3")+" score="+match.rules.last[0]+" secondsAfterRelease="+(match.Clock-flightStart).ToString("F3"));Write();}
 match.SetupScreen();report.AppendLine("ERRORS="+errors+". Software keyboard only; no launch velocity overrides, steering, or aftertouch. Camera-only manual render is not human or GPU performance validation.");File.WriteAllText(folder+"/result.txt",report.ToString());Debug.Log("TARGET_RANGE_COMPLETE "+report);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){Application.logMessageReceived-=Error;if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(original!=null)InputSystem.settings=original;if(settings!=null)Destroy(settings);Time.timeScale=1;}void OnDestroy(){Restore();}
#endif
}
}
